package com.autoops.command.risk;import org.springframework.stereotype.Service;import java.util.Locale;@Service public class CommandRiskAnalyzer{public Risk analyze(String c){String x=c.toLowerCase(Locale.ROOT);if(x.matches(".*\\b(rm|dnf|yum|rpm)\\b.*")||x.contains("mkfs")||x.contains("shutdown")||x.contains("reboot"))return Risk.HIGH;if(x.matches(".*\\b(systemctl|mv|cp|chmod|chown)\\b.*"))return Risk.MEDIUM;return Risk.LOW;}public enum Risk{LOW,MEDIUM,HIGH}}
